#!/usr/bin/env bash
set -Eeuo pipefail
rollback_deployment() { ROLLBACK_ID=$1; validate_deployment_id "$ROLLBACK_ID" || die 2 'invalid deployment ID'; begin_deployment rollback; verify_remote_target; require_rollback_confirmation; acquire_locks; create_full_backup; enable_maintenance; local source="$REMOTE_BACKUP_ROOT/$ROLLBACK_ID"; remote_exec "test -s $(shell_quote "$source/database-before.sql.gz") && test -f $(shell_quote "$source/wp-config-before.php") && test -f $(shell_quote "$source/rentacar-venezia-v2-before.tar.gz") && test -f $(shell_quote "$source/rentacar-core-before.tar.gz")" || die 8 'rollback backup is incomplete'; [ "$DRY_RUN" -eq 1 ] && { dry "would restore $ROLLBACK_ID database, wp-config, owned theme, plugin, and overwritten uploads"; return; }; remote_exec "cd $(shell_quote "$PRODUCTION_ROOT") && cp $(shell_quote "$source/wp-config-before.php") wp-config.php && $REMOTE_WP_COMMAND db reset --yes && gzip -dc $(shell_quote "$source/database-before.sql.gz") | $REMOTE_WP_COMMAND db import - && rm -rf wp-content/themes/rentacar-venezia-v2 wp-content/plugins/rentacar-core && tar -xzf $(shell_quote "$source/rentacar-venezia-v2-before.tar.gz") && tar -xzf $(shell_quote "$source/rentacar-core-before.tar.gz")" || die 8 'rollback restore failed'; restore_production_settings; flush_caches; verify_production; disable_maintenance; finish_deployment success; }
